// The Store's "Hurt by" table (GH-1076, D4): generated by asking a headless Sim's
// own focusHurts, committed, and pinned here. The oracles are literals, never
// read back from the generator's own arguments.
import { readdirSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import type { UnitTypeJson } from '../../packages/sim/src/sim';
import { askPair, buildThreatTable, THREAT_TABLE_PATH } from './store/threat-table';

const ROOT = resolve(__dirname, '../..');

function load(dir: string): UnitTypeJson[] {
  return readdirSync(resolve(ROOT, dir))
    .filter((f) => f.endsWith('.json'))
    .map((f) => JSON.parse(readFileSync(resolve(ROOT, dir, f), 'utf8')) as UnitTypeJson);
}
type Wpn = { can_target: string[] };
const weaponsOf = (u: UnitTypeJson): Wpn[] => (u as unknown as { weapons?: Wpn[] }).weapons ?? [];
const domainOf = (u: UnitTypeJson): 'air' | 'ground' =>
  (u as unknown as { mobility: { domain?: string } }).mobility.domain === 'air' ? 'air' : 'ground';

const kdf = load('data/units/kdf');
const enemies = load('data/units/enemy');
const armed = enemies.filter((e) => e.role !== 'wounded' && weaponsOf(e).length > 0);
const committed = JSON.parse(readFileSync(THREAT_TABLE_PATH, 'utf8')) as Record<string, string[]>;
const built = buildThreatTable();

describe('threat table', () => {
  it('the committed JSON is what the generator writes', () => {
    expect(built).toEqual(committed);
  });

  it('has keys and lists sorted', () => {
    expect(Object.keys(committed)).toEqual([...Object.keys(committed)].sort());
    for (const l of Object.values(committed)) expect(l).toEqual([...l].sort());
  });

  it('literals (R0.10)', () => {
    expect(committed['mbt_lavi']).toContain('atgm_cell');
    expect(committed['mbt_lavi']).not.toContain('sarim_rifles');
    expect(committed['air_medevac_heli']).toContain('manpad_team');
    // atgm_cell's Kornet is ground-only: absent from the air-domain drone's list.
    expect(committed['recon_drone']).not.toContain('atgm_cell');
    // wounded_sarim is excluded by role, never by id.
    expect(enemies.find((e) => e.id === 'wounded_sarim')?.role).toBe('wounded');
    for (const l of Object.values(committed)) expect(l).not.toContain('wounded_sarim');
  });

  it('the KDF unit presents its SIDE plate (R0.9): facing 16384 reads arc 1, facing 0 reads arc 0', () => {
    const atgm = enemies.find((e) => e.id === 'atgm_cell');
    const lavi = kdf.find((k) => k.id === 'mbt_lavi');
    if (atgm === undefined || lavi === undefined) throw new Error('fixture units missing');
    expect(askPair(atgm, lavi).arc).toBe(1);
    expect(askPair(atgm, lavi, 0).arc).toBe(0);
  });

  it('covers every KDF type, and the loops cannot pass empty', () => {
    expect(kdf.length).toBeGreaterThanOrEqual(30);
    expect(armed.length).toBeGreaterThanOrEqual(12);
    for (const k of kdf) expect(Object.keys(committed)).toContain(k.id);
    expect(Object.keys(committed).length).toBe(kdf.length);
  });

  it('a soft type lists every armed enemy that can reach its domain; a hard one a strict subset', () => {
    let soft = 0;
    let hard = 0;
    for (const k of kdf) {
      const dom = domainOf(k);
      const reach = armed.filter((e) => weaponsOf(e).some((w) => w.can_target.includes(dom))).map((e) => e.id).sort();
      const list = committed[k.id] ?? [];
      for (const id of list) expect(reach).toContain(id);
      if (list.length === reach.length) soft++;
      else hard++;
    }
    expect(soft).toBeGreaterThanOrEqual(1);
    expect(hard).toBeGreaterThanOrEqual(1);
  });

  it('a type with no armour on any face is soft by its own data, and lists EVERY armed enemy that can reach it', () => {
    // Softness comes from the unit JSON (armour 0 on all three faces), never from the list under test: a list that
    // lost an enemy would otherwise just be counted as "hard" by the loop above.
    const unarmoured = kdf.filter((k) => {
      const a = (k as unknown as { hull: { armor: Record<string, number> } }).hull.armor;
      return Object.values(a).every((v) => v === 0);
    });
    expect(unarmoured.map((k) => k.id).sort(), 'the soft set, by armour').toEqual(['attack_drone', 'recon_drone', 'wounded_kdf']);
    for (const k of unarmoured) {
      const dom = domainOf(k);
      const reach = armed.filter((e) => weaponsOf(e).some((w) => w.can_target.includes(dom))).map((e) => e.id).sort();
      expect(reach.length, `${k.id} is reachable by something`).toBeGreaterThan(0);
      expect(committed[k.id], k.id).toEqual(reach);
    }
  });
});
